static GtkWidget *named(GtkWidget *root,const char *name) { if(!g_strcmp0(gtk_widget_get_name(root),name)) return root;if(GTK_IS_CONTAINER(root)) { GList *c=gtk_container_get_children(GTK_CONTAINER(root));GtkWidget *f=NULL;for(GList *p=c;p && !f;p=p->next) f=named(p->data,name);g_list_free(c);return f; }return NULL; }
static GtkWidget *button(GtkWidget *root,const char *label) { if(GTK_IS_BUTTON(root) && !g_strcmp0(gtk_button_get_label(GTK_BUTTON(root)),label)) return root;if(GTK_IS_CONTAINER(root)) { GList *c=gtk_container_get_children(GTK_CONTAINER(root));GtkWidget *f=NULL;for(GList *p=c;p && !f;p=p->next) f=button(p->data,label);g_list_free(c);return f; }return NULL; }
static GtkWidget *dialog(const char *title) { GList *list=gtk_window_list_toplevels();GtkWidget *found=NULL;for(GList *p=list;p;p=p->next) if(GTK_IS_DIALOG(p->data) && !g_strcmp0(gtk_window_get_title(GTK_WINDOW(p->data)),title)) found=p->data;g_list_free(list);g_assert_nonnull(found);return found; }
static gboolean pick(gpointer data) { (void)data;GtkWidget *d=dialog("Open Project");gchar *current=gtk_file_chooser_get_filename(GTK_FILE_CHOOSER(d));gboolean ready=!g_strcmp0(current,choose_path);g_free(current);if(!ready) { gtk_file_chooser_set_filename(GTK_FILE_CHOOSER(d),choose_path);return G_SOURCE_CONTINUE; }gtk_dialog_response(GTK_DIALOG(d),GTK_RESPONSE_ACCEPT);return G_SOURCE_REMOVE; }
